import { Hero } from '@app/components/Hero';

const reasons = [
  {
    icon: <FileText className="icon-size-body" />,
    title: 'Capture everything',
    description: 'Add notes, counters, checklists and links in one ordered grid.',
  },
  {
    icon: <Zap className="icon-size-body" />,
    title: 'Stay in flow',
    description: 'Every change saves automatically with a clear Saving and Saved status.',
  },
  {
    icon: <Grid3X3 className="icon-size-body" />,
    title: 'Make it yours',
    description: 'Rename, resize and reorder widgets to fit how you think.',
  },
  {
    icon: <Lock className="icon-size-body" />,
    title: 'Always private',
    description: 'Your dashboards stay yours alone and survive every refresh.',
  },
];

function DashboardPreview() {
  return (
    <div data-ds="" className="flex-col-gap-4 p-4 rounded-surface border border-divider bg-surface-pageBg">
      <div data-ds="" className="flex-col-gap-3">
        <div data-ds="" className="grid gap-3" style={{ gridTemplateColumns: '1fr 1fr' }}>
          <Card>
            <Caption>Launch plan</Caption>
            <Paragraph>Outline for Q1 product launch — goals, timeline and owners.</Paragraph>
          </Card>
          <Card className="flex-col-gap-2 items-center justify-center">
            <Caption>Tasks completed</Caption>
            <Numeral className="text-display font-bold">
              12
            </Numeral>
          </Card>
        </div>
        <div data-ds="" className="grid gap-3" style={{ gridTemplateColumns: '1fr 1fr' }}>
          <Card>
            <Caption>To do</Caption>
            <div data-ds="" className="flex-col-gap-2">
              <label data-ds="" className="flex-row-gap-2 items-center">
                <Checkbox checked readOnly />
                <span className="text-sm line-through opacity-60">Review the draft</span>
              </label>
              <label data-ds="" className="flex-row-gap-2 items-center">
                <Checkbox readOnly />
                <span className="text-sm">Ship beta</span>
              </label>
            </div>
          </Card>
          <Card>
            <Caption>Links</Caption>
            <div data-ds="" className="flex-col-gap-2">
              <Link href="https://figma.com" target="_blank" rel="noreferrer">
                Figma
              </Link>
              <Link href="https://linear.app" target="_blank" rel="noreferrer">
                Linear
              </Link>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default function HomePage() {
  return (
    <>
      <Hero
        title="Your personal console, finally in one place"
        description="Your notes, numbers, tasks and links — together in a glowing dashboard that saves itself."
        actions={
          <Button as={NextLink} href="/sign-up">
            Create your first dashboard
          </Button>
        }
        media={<DashboardPreview />}
      />
      <Section>
        <div data-ds="" className="grid gap-6" style={{ gridTemplateColumns: 'repeat(2, 1fr)' }}>
          {reasons.map((reason) => (
            <div key={reason.title} data-ds="" className="flex-col-gap-3">
              <div data-ds="" className="flex-row-gap-2 items-center">
                <span data-ds="" className="text-primary-fg">
                  {reason.icon}
                </span>
                <h3 className="font-semibold">{reason.title}</h3>
              </div>
              <Paragraph color="muted">{reason.description}</Paragraph>
            </div>
          ))}
        </div>
      </Section>
    </>
  );
}

