display.text:
'use client';

import { PageHeader } from '@app/components/PageHeader';
import { useCurrentUser } from '@app/entities/auth';
import { Button } from '@packages/ui/Button';
import { Form } from '@packages/ui/Form';
import { PasswordInput } from '@packages/ui/Input';
import { Section } from '@packages/ui/Section';
import { DescriptionDetails, DescriptionList, DescriptionTerm } from '@packages/ui/Typography';
import { useForm } from 'react-hook-form';
import { Controller } from '@packages/ui/Form';
import { toast } from '@packages/ui/Toast';
import React, { useState } from 'react';
import { mockCall } from '@app/entities/mock';

type FormValues = { currentPassword: string; newPassword: string };

export default function AccountPage() {
  const user = useCurrentUser();
  const [formError, setFormError] = useState<string | undefined>();
  const { control, handleSubmit, reset } = useForm<FormValues>({
    defaultValues: { currentPassword: '', newPassword: '' },
  });

  const onSubmit = async (values: FormValues) => {
    setFormError(undefined);
    if (!values.currentPassword || values.newPassword.length < 8 || values.newPassword.length > 128) {
      setFormError('Current password is required and new password must be 8 to 128 characters');
      reset({ currentPassword: '', newPassword: '' });
      return;
    }
    // Simulate verifying current password: any non-empty current passes except "wrong"
    if (values.currentPassword === 'wrong') {
      setFormError('Current password is incorrect.');
      reset({ currentPassword: '', newPassword: '' });
      return;
    }
    try {
      await mockCall('updatePassword');
      toast('Password changed');
      reset({ currentPassword: '', newPassword: '' });
    } catch {
      setFormError('Could not update password. Try again.');
      reset({ currentPassword: '', newPassword: '' });
    }
  };

  return (
    <>
      <PageHeader title="Account" />
      <Section title="Your account">
        <DescriptionList>
          <DescriptionTerm>Email</DescriptionTerm>
          <DescriptionDetails>{user && typeof user === 'object' ? (user as { email: string }).email : ''}</DescriptionDetails>
        </DescriptionList>
      </Section>
      <Section title="Change password">
        <Form
          error={formError}
          onSubmit={handleSubmit(onSubmit)}
          actions={
            <>
              <Button type="submit">Save</Button>
            </>
          }
        >
          <Controller
            name="currentPassword"
            control={control}
            rules={{ required: true }}
            render={({ field, fieldState }) => (
              <PasswordInput
                label="Current password"
                autoComplete="current-password"
                {...field}
              />
            )}
          />
          <Controller
            name="newPassword"
            control={control}
            rules={{ required: true }}
            render={({ field }) => (
              <PasswordInput
                label="New password"
                autoComplete="new-password"
                {...field}
              />
            )}
          />
        </Form>
      </Section>
    </>
  );
}

