input.content:
'use client';

import { DeleteDashboardDialog } from '@app/blocks/DeleteDashboardDialog';
import { PageHeader } from '@app/components/PageHeader';
import { NextLink } from '@app/components/NextLink';
import { NotFound } from '@app/components/NotFound';
import { useGetDashboard, duplicateDashboard, updateDashboard } from '@app/entities/dashboard';
import {
  useListWidgets,
  createWidget,
  deleteWidget,
  updateWidgetTitle,
  repositionWidget,
  resizeWidget,
  updateNoteText,
  incrementCounter,
  updateCounterLabel,
  addChecklistItem,
  toggleChecklistItem,
  updateChecklistItem,
  removeChecklistItem,
  addLink,
  updateLink,
  removeLink,
} from '@app/entities/widget';
import { useWidgetStore } from '@app/entities/widget/store';
import { Button, IconButton } from '@packages/ui/Button';
import { Card } from '@packages/ui/Card';
import { CardList } from '@packages/ui/Card';
import { Checkbox } from '@packages/ui/Checkbox';
import { Dialog } from '@packages/ui/Dialog';
import { Dropdown } from '@packages/ui/Dropdown';
import { Input, SearchInput } from '@packages/ui/Input';
import { Textarea } from '@packages/ui/Textarea';
import { Select } from '@packages/ui/Select';
import { Link } from '@packages/ui/Link';
import { Numeral } from '@packages/ui/Numeral';
import { toast } from '@packages/ui/Toast';
import { Time, Paragraph, Caption } from '@packages/ui/Typography';
import {
  Check,
  X,
  Pencil,
  Trash2,
  Plus,
  Minus,
  Copy,
  Settings,
  GripVertical,
  ChevronUp,
  ChevronDown,
  ExternalLink,
} from 'lucide-react';
import { useParams, useRouter } from 'next/navigation';
import React, { useState, useMemo } from 'react';

import type { Widget } from '@app/entities/widget/types';

function SaveStatus({ saving, saved }: { saving: boolean; saved: boolean }) {
  if (saving) return <span>Saving</span>;
  if (saved) return <span>Saved</span>;
  return null;
}

export default function DashboardDetailPage() {
  const params = useParams<{ dashboardId: string }>();
  const dashboardId = params.dashboardId;
  const { data: dashboard, loading: dashLoading, error: dashError, retry } = useGetDashboard(dashboardId);
  const { data: allWidgets, loading: widgetsLoading } = useListWidgets();
  const router = useRouter();

  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [dashEdit, setDashEdit] = useState(false);
  const [dashName, setDashName] = useState('');
  const [dashErrorMsg, setDashErrorMsg] = useState<string | undefined>();
  const [showDelete, setShowDelete] = useState(false);
  const [showAddWidget, setShowAddWidget] = useState(false);
  const [newType, setNewType] = useState<string>('note');
  const [newTitle, setNewTitle] = useState('');
  const [newSize, setNewSize] = useState<string>('medium');
  const [newWidgetError, setNewWidgetError] = useState<string | undefined>();
  const [removeWidgetId, setRemoveWidgetId] = useState<string | null>(null);
  const [editLinkWidget, setEditLinkWidget] = useState<Widget | null>(null);
  const [editLinkIndex, setEditLinkIndex] = useState<number | null>(null);
  const [linkTitle, setLinkTitle] = useState('');
  const [linkUrl, setLinkUrl] = useState('');
  const [linkError, setLinkError] = useState<string | undefined>();
  const [editingWidgetTitle, setEditingWidgetTitle] = useState<string | null>(null);
  const [widgetTitleDraft, setWidgetTitleDraft] = useState('');
  const [widgetTitleError, setWidgetTitleError] = useState<string | undefined>();
  const [addingChecklist, setAddingChecklist] = useState<Record<string, string>>({});
  const [editingChecklist, setEditingChecklist] = useState<{ widgetId: string; index: number } | null>(null);
  const [checklistDraft, setChecklistDraft] = useState('');
  const [editingCounterLabel, setEditingCounterLabel] = useState<string | null>(null);
  const [counterLabelDraft, setCounterLabelDraft] = useState('');

  const widgets = useMemo(() => {
    if (!allWidgets) return [];
    return allWidgets
      .filter((w) => w.dashboard === dashboardId)
      .sort((a, b) => a.position - b.position);
  }, [allWidgets, dashboardId]);

  if (dashLoading || widgetsLoading) return <PageHeader title="Loading" />;
  if (dashError)
    return (
      <>
        <PageHeader title="Error" />
        <p role="alert">Failed to load</p>
        <Button onClick={retry}>Retry</Button>
      </>
    );
  if (!dashboard) {
    return <NotFound title="Dashboard not found" description="This dashboard is gone." action={{ label: 'Go to your dashboards', href: '/dashboards' }} />;
  }

  const flashSaved = () => {
    setSaving(true);
    setTimeout(() => {
      setSaving(false);
      setSaved(true);
      setTimeout(() => setSaved(false), 1500);
    }, 300);
  };

  const handleSaveDashboardName = async () => {
    if (!dashName.trim() || dashName.length > 80) {
      setDashErrorMsg('Name is required and max 80 characters');
      return;
    }
    try {
      await updateDashboard(dashboard.id, { name: dashName, lastEditedAt: new Date().toISOString() });
      toast({ title: 'Dashboard saved' });
      flashSaved();
      setDashEdit(false);
    } catch {
      setDashErrorMsg('Could not save. Try again.');
    }
  };

  const handleDuplicate = async () => {
    try {
      const copy = await duplicateDashboard({ name: `${dashboard.name} Copy`, lastEditedAt: new Date().toISOString() });
      const now = new Date().toISOString();
      for (const w of widgets) {
        useWidgetStore.setState(({ records }) => ({
          records: [...records, { ...w, id: crypto.randomUUID(), dashboard: copy.id, createdAt: now, updatedAt: now }],
        }));
      }
      router.push(`/dashboards/${copy.id}`);
    } catch {
      toast({ title: 'Could not duplicate. Try again.', status: 'error' });
    }
  };

  const handleCreateWidget = async () => {
    if (!newType) {
      setNewWidgetError('Title max 60 characters and type is required');
      return;
    }
    if (newTitle.length > 60) {
      setNewWidgetError('Title max 60 characters and type is required');
      return;
    }
    try {
      const title = newTitle || newType.charAt(0).toUpperCase() + newType.slice(1);
      const position = widgets.length + 1;
      await createWidget({
        title,
        type: newType as Widget['type'],
        size: newSize as Widget['size'],
        position,
        dashboard: dashboardId,
        noteText: '',
        counterLabel: '',
        counterValue: 0,
        checklistItemText: [],
        checklistChecked: [],
        linkTitle: [],
        linkUrl: [],
      } as never);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
      flashSaved();
      toast({ title: 'Widget created' });
      setShowAddWidget(false);
      setNewTitle('');
      setNewWidgetError(undefined);
    } catch {
      setNewWidgetError('Could not create widget. Try again.');
    }
  };

  const handleRemoveWidget = async () => {
    if (!removeWidgetId) return;
    try {
      await deleteWidget(removeWidgetId);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
      flashSaved();
      toast({ title: 'Widget removed' });
      setRemoveWidgetId(null);
    } catch {
      toast({ title: 'Could not remove widget. Try again.', status: 'error' });
    }
  };

  const handleWidgetTitleSave = async (w: Widget) => {
    if (widgetTitleDraft.length > 60) {
      setWidgetTitleError('Max 60 characters');
      return;
    }
    try {
      await updateWidgetTitle(w.id, { title: widgetTitleDraft } as never);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
      flashSaved();
      setEditingWidgetTitle(null);
      setWidgetTitleError(undefined);
    } catch {
      setWidgetTitleError('Saving failed. Try again.');
    }
  };

  const handleMove = async (w: Widget, dir: number) => {
    const idx = widgets.findIndex((x) => x.id === w.id);
    const ni = idx + dir;
    if (ni < 0 || ni >= widgets.length) return;
    const other = widgets[ni];
    try {
      await repositionWidget(w.id, { position: other.position } as never);
      await repositionWidget(other.id, { position: w.position } as never);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
      flashSaved();
    } catch {
      toast({ title: 'Saving failed. Try again.', status: 'error' });
    }
  };

  const handleResize = async (w: Widget, size: string) => {
    try {
      await resizeWidget(w.id, { size } as never);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
      flashSaved();
    } catch {
      toast({ title: 'Saving failed. Try again.', status: 'error' });
    }
  };

  return (
    <>
      <PageHeader
        title={
          dashEdit ? (
            <span className="flex-row-gap-2 items-center">
              <Input aria-label="Dashboard name" value={dashName} onChange={setDashName} error={dashErrorMsg} />
              <IconButton tooltip="Save" onClick={handleSaveDashboardName}>
                <Check />
              </IconButton>
              <IconButton tooltip="Cancel" onClick={() => setDashEdit(false)}>
                <X />
              </IconButton>
            </span>
          ) : (
            dashboard.name
          )
        }
        breadcrumb={[{ label: 'Back to dashboards', href: '/dashboards' }]}
        actions={
          editing ? (
            <>
              <Button onClick={() => setShowAddWidget(true)}>Add widget</Button>
              <Button onClick={handleDuplicate}>Duplicate</Button>
              <Button
                // destructive
                variant="danger"
                onClick={() => setShowDelete(true)}
              >
                Delete
              </Button>
              <Button onClick={() => setEditing(false)}>Done</Button>
            </>
          ) : (
            <Button onClick={() => { setEditing(true); setDashName(dashboard.name); }}>Edit</Button>
          )
        }
      />
      {!editing && !dashEdit ? (
        <div data-ds="" className="flex-row-gap-2 items-center">
          <SaveStatus saving={saving} saved={saved} />
        </div>
      ) : null}
      {editing && !dashEdit ? (
        <div data-ds="" className="flex-row-gap-2 items-center">
          <span>Editing: </span>
          <Input
            aria-label="Dashboard name"
            value={dashName}
            onChange={(v) => setDashName(v)}
            error={dashErrorMsg}
          />
          <IconButton tooltip="Save" onClick={handleSaveDashboardName}>
            <Check />
          </IconButton>
          <IconButton tooltip="Cancel" onClick={() => { setDashEdit(false); setDashName(dashboard.name); }}>
            <X />
          </IconButton>
          <Button onClick={() => setDashEdit(true)}>Edit name</Button>
        </div>
      ) : null}

      {widgets.length === 0 ? (
        <div data-ds="" className="flex-col-gap-3 items-start">
          <p>No widgets yet. Add your first widget to start building.</p>
          <Button onClick={() => setShowAddWidget(true)}>Add widget</Button>
        </div>
      ) : (
        <div data-ds="" className="flex-col-gap-4">
          {widgets.map((w) => (
            <Card key={w.id}>
              <div data-ds="" className="flex-row-gap-2 items-center">
                {editing && editingWidgetTitle === w.id ? (
                  <>
                    <Input aria-label="Widget title" value={widgetTitleDraft} onChange={setWidgetTitleDraft} error={widgetTitleError} />
                    <IconButton tooltip="Save" onClick={() => handleWidgetTitleSave(w)}>
                      <Check />
                    </IconButton>
                    <IconButton tooltip="Cancel" onClick={() => setEditingWidgetTitle(null)}>
                      <X />
                    </IconButton>
                  </>
                ) : (
                  <>
                    <h3>{w.title || w.type.charAt(0).toUpperCase() + w.type.slice(1)}</h3>
                    {editing ? (
                      <IconButton
                        tooltip="Edit title"
                        onClick={() => { setEditingWidgetTitle(w.id); setWidgetTitleDraft(w.title || ''); }}
                      >
                        <Pencil />
                      </IconButton>
                    ) : null}
                  </>
                )}
                {editing ? (
                  <>
                    <IconButton
                      tooltip={widgets.length === 1 ? 'Add another widget to reorder' : 'Move up'}
                      disabled={widgets.length === 1}
                      onClick={() => handleMove(w, -1)}
                    >
                      <ChevronUp />
                    </IconButton>
                    <IconButton
                      tooltip={widgets.length === 1 ? 'Add another widget to reorder' : 'Move down'}
                      disabled={widgets.length === 1}
                      onClick={() => handleMove(w, 1)}
                    >
                      <ChevronDown />
                    </IconButton>
                    <Dropdown
                      menu={
                        <>
                          <Dropdown.Item onSelect={() => handleResize(w, 'small')}>Small</Dropdown.Item>
                          <Dropdown.Item onSelect={() => handleResize(w, 'medium')}>Medium</Dropdown.Item>
                          <Dropdown.Item onSelect={() => handleResize(w, 'large')}>Large</Dropdown.Item>
                        </>
                      }
                    >
                      <IconButton tooltip="Change size">
                        <Settings />
                      </IconButton>
                    </Dropdown>
                    <IconButton tooltip="Remove" onClick={() => setRemoveWidgetId(w.id)}>
                      <Trash2 />
                    </IconButton>
                  </>
                ) : null}
              </div>

              {/* widget content */}
              {w.type === 'note' ? (
                <Textarea
                  aria-label="Note text"
                  value={w.noteText || ''}
                  onChange={async (v) => {
                    if (v.length > 5000) return;
                    try {
                      await updateNoteText(w.id, { noteText: v } as never);
                      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
                      flashSaved();
                    } catch {
                      toast({ title: 'Saving failed. Try again.', status: 'error' });
                    }
                  }}
                  placeholder="Write your note"
                />
              ) : null}
              {w.type === 'counter' ? (
                <div data-ds="" className="flex-col-gap-3">
                  {editing && editingCounterLabel === w.id ? (
                    <span className="flex-row-gap-2 items-center">
                      <Input
                        aria-label="Counter label"
                        value={counterLabelDraft}
                        onChange={setCounterLabelDraft}
                      />
                      <IconButton
                        tooltip="Save"
                        onClick={async () => {
                          if (counterLabelDraft.length > 40) {
                            toast({ title: 'Max 40 characters', status: 'error' });
                            return;
                          }
                          try {
                            await updateCounterLabel(w.id, { counterLabel: counterLabelDraft } as never);
                            flashSaved();
                            setEditingCounterLabel(null);
                          } catch {
                            toast({ title: 'Saving failed. Try again.', status: 'error' });
                          }
                        }}
                      >
                        <Check />
                      </IconButton>
                      <IconButton tooltip="Cancel" onClick={() => setEditingCounterLabel(null)}>
                        <X />
                      </IconButton>
                    </span>
                  ) : (
                    <span className="flex-row-gap-2 items-center">
                      <span>{w.counterLabel || 'Count'}</span>
                      <IconButton
                        tooltip="Edit label"
                        onClick={() => { setEditingCounterLabel(w.id); setCounterLabelDraft(w.counterLabel || ''); }}
                      >
                        <Pencil />
                      </IconButton>
                    </span>
                  )}
                  <div data-ds="" className="flex-row-gap-3 items-center">
                    <IconButton
                      tooltip="Decrease"
                      onClick={async () => {
                        try {
                          await incrementCounter(w.id, { counterValue: (w.counterValue ?? 0) - 1 } as never);
                          await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
                          flashSaved();
                        } catch {
                          toast({ title: 'Saving failed. Try again.', status: 'error' });
                        }
                      }}
                    >
                      <Minus />
                    </IconButton>
                    <Numeral>{w.counterValue ?? 0}</Numeral>
                    <IconButton
                      tooltip="Increase"
                      onClick={async () => {
                        try {
                          await incrementCounter(w.id, { counterValue: (w.counterValue ?? 0) + 1 } as never);
                          await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
                          flashSaved();
                        } catch {
                          toast({ title: 'Saving failed. Try again.', status: 'error' });
                        }
                      }}
                    >
                      <Plus />
                    </IconButton>
                  </div>
                </div>
              ) : null}
              {w.type === 'checklist' ? (
                <div data-ds="" className="flex-col-gap-3">
                  {(w.checklistItemText || []).map((text, idx) => (
                    <div key={idx} data-ds="" className="flex-row-gap-2 items-center">
                      <Checkbox
                        checked={w.checklistChecked?.[idx] ?? false}
                        onCheckedChange={async (checked) => {
                          const next = [...(w.checklistChecked || [])];
                          next[idx] = checked;
                          try {
                            await toggleChecklistItem(w.id, { checklistChecked: next } as never);
                            flashSaved();
                          } catch {
                            toast({ title: 'Saving failed. Try again.', status: 'error' });
                          }
                        }}
                        aria-label={text}
                      />
                      {editingChecklist?.widgetId === w.id && editingChecklist.index === idx ? (
                        <>
                          <Input
                            aria-label="Checklist item text"
                            value={checklistDraft}
                            onChange={setChecklistDraft}
                          />
                          <IconButton
                            tooltip="Save"
                            onClick={async () => {
                              if (!checklistDraft.trim() || checklistDraft.length > 120) {
                                toast({ title: 'Text is required and max 120 characters', status: 'error' });
                                return;
                              }
                              const next = [...(w.checklistItemText || [])];
                              next[idx] = checklistDraft;
                              try {
                                await updateChecklistItem(w.id, { checklistItemText: next } as never);
                                flashSaved();
                                setEditingChecklist(null);
                              } catch {
                                toast({ title: 'Saving failed. Try again.', status: 'error' });
                              }
