                    />
                    <Button
                      onClick={async () => {
                        const v = (addingChecklist[w.id] || '').trim();
                        if (!v || v.length > 120) {
                          toast({ title: 'Text is required and max 120 characters', status: 'error' });
                          return;
                        }
                        try {
                          await addChecklistItem(w.id, { checklistItemText: [...(w.checklistItemText || []), v], checklistChecked: [...(w.checklistChecked || []), false] } as never);
                          setAddingChecklist((s) => ({ ...s, [w.id]: '' }));
                          flashSaved();
                        } catch {
                          toast({ title: 'Saving failed. Try again.', status: 'error' });
                        }
                      }}
                    >
                      Add
                    </Button>
                  </span>
                </div>
              ) : null}
              {w.type === 'link_list' ? (
                <div data-ds="" className="flex-col-gap-3">
                  {(w.linkTitle || []).map((t, idx) => (
                    <div key={idx} data-ds="" className="flex-row-gap-2 items-center">
                      <Link href={w.linkUrl?.[idx] || '#'} target="_blank" rel="noreferrer">
