      )}

      {/* Delete dashboard dialog */}
      {showDelete ? (
        <DeleteDashboardDialog
          dashboardId={dashboard.id}
          dashboardName={dashboard.name}
          open={showDelete}
          onOpenChange={setShowDelete}
          onDeleted={() => router.push('/dashboards')}
        />
      ) : null}

      {/* Add widget dialog */}
      <Dialog
        title="Add widget"
        open={showAddWidget}
        onOpenChange={setShowAddWidget}
        footer={(close) => (
          <>
            <Button onClick={() => close()}>Cancel</Button>
            <Button onClick={handleCreateWidget}>Create</Button>
          </>
        )}
      >
        <div data-ds="" className="flex-col-gap-3">
          <Select label="Type" value={newType} onChange={setNewType} options={[{ value: 'note', label: 'Note' }, { value: 'counter', label: 'Counter' }, { value: 'checklist', label: 'Checklist' }, { value: 'link_list', label: 'Link list' }]} />
          <Input label="Title" value={newTitle} onChange={setNewTitle} />
          <Select label="Size" value={newSize} onChange={setNewSize} options={[{ value: 'small', label: 'Small' }, { value: 'medium', label: 'Medium' }, { value: 'large', label: 'Large' }]} />
          {newWidgetError ? <p role="alert">{newWidgetError}</p> : null}
        </div>
      </Dialog>

      {/* Remove widget dialog */}
      <Dialog
        title="Remove this widget?"
        open={!!removeWidgetId}
        onOpenChange={(o) => !o && setRemoveWidgetId(null)}
        footer={(close) => (
          <>
            <Button onClick={() => close()}>Cancel</Button>
            <Button
              variant="danger"
              onClick={handleRemoveWidget}
            >
              Remove
            </Button>
          </>
        )}
      >
        <p>This will permanently delete the widget and its contents. This cannot be undone.</p>
      </Dialog>

      {/* Link dialog */}
      <Dialog
        title={editLinkIndex !== null ? 'Edit link' : 'Add link'}
        open={!!editLinkWidget}
        onOpenChange={(o) => !o && setEditLinkWidget(null)}
        footer={(close) => (
          <>
            <Button onClick={() => close()}>Cancel</Button>
            <Button
              onClick={async () => {
                if (!linkTitle.trim() || linkTitle.length > 80 || !linkUrl.trim() || !/^https?:\/\/.+/.test(linkUrl)) {
                  setLinkError('Title is required max 80 and URL must be valid http/https');
                  return;
                }
                if (!editLinkWidget) return;
                try {
                  if (editLinkIndex !== null) {
                    const nt = [...(editLinkWidget.linkTitle || [])];
                    const nu = [...(editLinkWidget.linkUrl || [])];
                    nt[editLinkIndex] = linkTitle;
                    nu[editLinkIndex] = linkUrl;
                    await updateLink(editLinkWidget.id, { linkTitle: nt, linkUrl: nu } as never);
                  } else {
                    await addLink(editLinkWidget.id, { linkTitle: [...(editLinkWidget.linkTitle || []), linkTitle], linkUrl: [...(editLinkWidget.linkUrl || []), linkUrl] } as never);
                  }
                  await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() });
                  flashSaved();
                  toast({ title: 'Link saved' });
                  setEditLinkWidget(null);
                } catch {
                  setLinkError('Could not save link. Try again.');
                }
              }}
            >
              Save
            </Button>
          </>
        )}
      >
        <div data-ds="" className="flex-col-gap-3">
          <Input label="Link title" value={linkTitle} onChange={setLinkTitle} />
          <Input label="Link URL" value={linkUrl} onChange={setLinkUrl} placeholder="https://" />
          {linkError ? <p role="alert">{linkError}</p> : null}
        </div>
      </Dialog>
    </>
  );
}

