// Usage: the patterns to copy.
type EventStatus = 'On sale' | 'Sold out' | 'Draft' | 'Cancelled';

type EventRow = {
  id: string;
  name: string;
  organizer: string;
  venue: string;
  ticketPrice: number;
  capacity: number;
  ticketsSold: number;
